-- Staging tables mirror the supplied CSV headers. All columns are text to avoid lossy imports.
CREATE TABLE IF NOT EXISTS stg_bus_route_pairs (vehicle_number text, route_id text, route_name text, first_stop text, last_stop text, source_timestamp text);
CREATE TABLE IF NOT EXISTS stg_assignments (service_date text, vehicle_number text, route_id text, route_name text, first_stop text, last_stop text, driver_id text, conductor_id text, assignment_type text, driver_name text, conductor_name text);
CREATE TABLE IF NOT EXISTS stg_reviews (review_id text, category text, scenario text, sentiment text, severity text, rating text, route text, "timestamp" text, time_of_day text, review text, service_date text, assigned_vehicle_number text, assigned_route_id text, assigned_route_name text, assigned_first_stop text, assigned_last_stop text, driver_id text, conductor_id text, assignment_type text, is_negative text, negative_count text, original_review_id text, source_dataset text);
